import { writeFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";

export function gcodeFixture() {
	const lines = [
		"; Original OpenSCAD.js viewer calibration fixture, Apache-2.0.",
		"; Synthetic visualization/test data only; not prepared for printing.",
		"; No printer-profile macros, homing, heating or shutdown sequences.",
		"; generated by OpenSCAD.js fixture generator",
		"; total layer number: 55",
		"; printer_model = Synthetic test printer",
		"; filament_colour = #000000;#FF00FF;#FFFF00;#0080FF;#FFFFFF",
		"; bed_shape = 0x0,200x0,200x200,0x200",
		"; max_print_height = 200",
		"G21", "G90", "M82", "G92 E0",
		"G1 X5 Y5 F6000", "G1 Z0.2",
		";TYPE:Custom",
		"G1 X15 Y5 E1 F1800",
		"G1 X30 Y30 F6000",
	];
	let extrusion = 1;
	for (let layer = 1; layer <= 55; layer++) {
		lines.push(";LAYER_CHANGE", `G1 Z${(layer * 0.2).toFixed(1)}`, ";TYPE:Outer wall");
		for (const [x, y] of [[50, 30], [50, 40], [30, 40], [30, 30]]) {
			extrusion += 0.5;
			lines.push(`G1 X${x} Y${y} E${extrusion.toFixed(2)} F1800`);
		}
	}
	lines.push(
		"; Synthetic metadata for parser tests; not a slicer estimate.",
		"; estimated printing time (normal mode) = 2m 3s",
		"; filament used [mm] = 56,55",
		"; filament used [g] = 0.14,0.14",
	);
	return lines.join("\n") + "\n";
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
	const output = new URL("../references/scad sample files/viewer-calibration.gcode", import.meta.url);
	await writeFile(output, gcodeFixture());
	console.log(`Generated ${fileURLToPath(output)}`);
}
